from src.nodes.base import BaseNode
from src.runtime.assets.assembly.clearance_validator import get_clearance_validator
from src.runtime.assets.assembly.spatial_metadata import SpatialMetadata
import json

class Hou_Mcp_Clearance_Validator(BaseNode):
    name = "hou_mcp_clearance_validator"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("placements_json", "string", widget_type="text", default="[]")
        self.add_output("clearance_report_json", "string")
        self.add_output("violation_count",       "int")
        self.add_output("ok",                    "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        placements_json = str(inputs.get("placements_json", "[]") or "[]")
        try:
            raw = json.loads(placements_json)
        except Exception as exc:
            self.log_error(f"Failed to parse placements_json: {exc}")
            return {"clearance_report_json": "{}", "violation_count": 0, "ok": True, "exec_out": True}

        try:
            placements = []
            for item in raw:
                aid  = str(item.get("asset_id", ""))
                pos  = tuple(item.get("position", [0.0, 0.0, 0.0]))
                meta = SpatialMetadata.from_dict(item.get("spatial_metadata") or {})
                placements.append((aid, pos, meta))

            report = get_clearance_validator().validate_scene_clearance(placements)
            self.log_info(f"Clearance validation: {report.violation_count} violation(s). ok={report.ok}")
            if not report.ok:
                for v in report.violations[:3]:
                    self.log_warning(f"  Clearance: {v.asset_a} ({v.type_a}) ↔ {v.asset_b} ({v.type_b}) shortfall={v.shortfall:.2f}m")
            return {
                "clearance_report_json": json.dumps(report.to_dict(), sort_keys=True, default=str),
                "violation_count":       report.violation_count,
                "ok":                    report.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Clearance validation failed: {exc}")
            return {"clearance_report_json": "{}", "violation_count": 0, "ok": True, "exec_out": True}

def register_node():
    return Hou_Mcp_Clearance_Validator
